int purge_expired(const char *path) {
  sqlite3 *db = NULL;
  sqlite3_stmt *stmt = NULL;
  int rc = sqlite3_open(path, &db);
  if (rc != SQLITE_OK) {
    fprintf(stderr, "open %s: %s\n", path, sqlite3_errmsg(db));
    sqlite3_close(db);
    return rc;
  }
  rc = sqlite3_prepare_v2(db, "DELETE FROM sessions WHERE expires_at < strftime('%s', 'now')", -1, &stmt, NULL);
  if (rc == SQLITE_OK) {
    rc = sqlite3_step(stmt);
  }
  if (rc != SQLITE_DONE) {
    fprintf(stderr, "purge: %s\n", sqlite3_errmsg(db));
  }
  sqlite3_finalize(stmt);
  sqlite3_close(db);
  return rc == SQLITE_DONE ? SQLITE_OK : rc;
}

if (rc != SQLITE_DONE) {
  fprintf(stderr, "purge: %s\n", sqlite3_errmsg(db));
} else {
  fprintf(stderr, "purge: %d rows\n", sqlite3_changes(db));
}
